import{_ as l,l as i,o as e,c as s,v as r,p as d,x as t,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"FPGA 布局布线","description":"","frontmatter":{"title":"FPGA 布局布线","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fpga-place-route.md","filePath":"cs/fpga-place-route.md","lastUpdated":1789023840000}'),A={name:"cs/fpga-place-route.md"};function B(E,a,h,u,P,T){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="fpga-布局布线" tabindex="-1">FPGA 布局布线 <a class="header-anchor" href="#fpga-布局布线" aria-label="Permalink to &quot;FPGA 布局布线&quot;">​</a></h1><div class="epigraph"><p>逻辑映射之后仍不知道哪一列 CLB 被占用、哪一段开关盒接通；布局布线决定线延迟，从而改写 STA 的 slack。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Betz, Rose, Marquardt, Architecture and CAD for Deep-Submicron FPGAs 整理</footer></div><p><a href="/cs/fpga-lut-clb">上一课</a>给出 LUT/CLB 砖块。综合网表仍是逻辑连接。缺口是 <strong>place and route</strong>：把实例放到二维阵列，再在布线通道里接通，得到可下载的比特流与真实延迟。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FPGA 布线是预制的分段导线加开关晶体管，不是 ASIC 那样任意金属形状（ASIC 流程后课再讲）。布局：邻近的 CLB 应放近，DSP/BRAM 是稀疏硬核，算术单元的乘法器必须「靠」DSP 列。布线失败（不可布）或延迟过大导致<a href="/cs/sta">STA</a> 负 slack。缺口不是再解释 LUT，而是这层物理对应。</p><p>时序驱动布局用 STA 的关键网加权。时钟用专用全局/区域网络，普通信号不要抢时钟树。</p><h3 id="比特流不是「网表的压缩包」" tabindex="-1">比特流不是「网表的压缩包」 <a class="header-anchor" href="#比特流不是「网表的压缩包」" aria-label="Permalink to &quot;比特流不是「网表的压缩包」&quot;">​</a></h3><p>比特流编码的是 SRAM LUT 初值与开关盒通断，格式专有。把 <code>.bit</code> 当另一份 Verilog 阅读，逆向与安全是另一课；本课只承认：功能与时序在 P&amp;R 之后才封闭。</p><p><span class="marginnote">Betz/Rose 的 VPR 教材是 FPGA CAD 经典。Harris 描述设计流程：综合→映射→布局→布线→时序。本课不教某 IDE 的点击顺序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><ol><li>映射已在上一课。2. 打包 CLB。3. 布局最小化线长与时序代价。4. 布线分配通道；拥塞则绕路，延迟上升。5. 静态时序签核；失败则改 RTL、约束或再优化。引脚锁定影响边缘延迟。</li></ol>',11)),(e(),d(c,null,{default:t(()=>[p(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAP%5B%22LUT%20%E6%98%A0%E5%B0%84%22%5D%20--%3E%20PL%5B%22%E5%B8%83%E5%B1%80%E5%88%B0%E9%98%B5%E5%88%97%22%5D%0A%20%20PL%20--%3E%20RT%5B%22%E5%BC%80%E5%85%B3%E7%9B%92%E5%B8%83%E7%BA%BF%22%5D%0A%20%20RT%20--%3E%20BIT%5B%22%E6%AF%94%E7%89%B9%E6%B5%81%22%5D%0A%20%20RT%20--%3E%20STA%5B%22%E6%97%B6%E5%BA%8F%E7%AD%BE%E6%A0%B8%22%5D%0A%20%20STA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AHLS%20%E4%BB%8E%E6%9B%B4%E9%AB%98%E5%B1%82%E8%BF%9B%E6%9D%A5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>跨时钟 FIFO 的两时钟必须各接到合法时钟网络，否则工具用普通布线走时钟，skew 不可控。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课 HLS 仍然经过同一 P&amp;R；只是 RTL 由工具生成。ASIC 布局布线没有开关盒，但「时序闭合」同一目标。本课把 FPGA 的物理闭环钉死，让后面的功耗与验证知道延迟来自布线，不是来自 <code>#delay</code>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论部分重配置的全部安全模型，不把 PCB 走线当 FPGA 内部布线。不进入光刻分辨率与金属层——FPGA 对用户是已造好的阵列。</p><p>后课默认：FPGA 时序在布局布线后才真实；DSP/BRAM 位置是一等约束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LUT 映射之后还要放置 CLB 并接通开关盒。</li><li>线延迟进入 STA；时钟走专用网络。</li><li>比特流是配置 SRAM，不是可读网表。</li><li>出处：Harris and Harris；Betz, Rose, Marquardt。</li></ul>',8))])}const m=l(A,[["render",B]]);export{f as __pageData,m as default};
